package club.abelix.games.fakevival.managers;

import club.abelix.games.fakevival.util.CC;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.block.data.BlockData;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.block.Action;
import org.bukkit.event.player.*;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.util.BoundingBox;

import java.util.*;

public final class AdminWorldEditManager implements Listener {
    private static final long MAX_BLOCKS = 250_000L;
    private static final int MAX_HISTORY = 10;
    private static final int MAX_RADIUS = 50;
    private static final int MAX_HEIGHT = 256;
    private static final int MAX_POLY_POINTS = 128;
    private static final int MAX_PREVIEW_PARTICLES = 500;
    private static final double MAX_VISUAL_DISTANCE_SQUARED = 128D * 128D;
    private static final Set<String> COMMANDS = Set.of("wand","pos1","pos2","set","walls","replace","undo","copy",
            "paste","cut","clear","size","count","expand","contract","shift","sphere","hsphere","cyl","hcyl","cancel",
            "sel","selection","selinfo","poly","selpreview","selvisual","selectionvisual","wevisual");
    private final JavaPlugin plugin;
    private final SpawnProtectionManager spawn;
    private final ZoneManager zones;
    private final GuildManager guilds;
    private final DiscordWebhookManager webhook;
    private final NamespacedKey wandKey;
    private final NamespacedKey furnitureKey;
    private final NamespacedKey npcKey;
    private final Map<UUID, Selection> selections = new HashMap<>();
    private final Map<UUID, SelectionType> selectionTypes = new HashMap<>();
    private final Map<UUID, Boolean> selectionVisualEnabled = new HashMap<>();
    private final Map<UUID, ZoneVisual> zoneVisuals = new HashMap<>();
    private final Map<UUID, Clipboard> clipboards = new HashMap<>();
    private final Map<UUID, Deque<UndoSnapshot>> histories = new HashMap<>();
    private final Map<UUID, Task> active = new LinkedHashMap<>();
    private int schedulerTask = -1;

    public AdminWorldEditManager(JavaPlugin plugin, SpawnProtectionManager spawn, ZoneManager zones,
                                 GuildManager guilds, DiscordWebhookManager webhook) {
        this.plugin=plugin;this.spawn=spawn;this.zones=zones;this.guilds=guilds;this.webhook=webhook;
        this.wandKey=new NamespacedKey(plugin,"smp_worldedit_wand");
        this.furnitureKey=new NamespacedKey(plugin,"smp_furniture");
        this.npcKey=new NamespacedKey(plugin,"fakevival_npc");
        schedulerTask=Bukkit.getScheduler().scheduleSyncRepeatingTask(plugin,this::tick,1L,1L);
    }

    @EventHandler(priority=EventPriority.LOWEST)
    public void onDoubleSlash(PlayerCommandPreprocessEvent event){String message=event.getMessage();if(!message.startsWith("//"))return;String raw=message.substring(2).trim();if(raw.isEmpty())return;String[]args=raw.split("\\s+");if(!COMMANDS.contains(args[0].toLowerCase(Locale.ROOT)))return;event.setCancelled(true);handle(event.getPlayer(),args,0);}

    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false)
    public void onWand(PlayerInteractEvent event){if(event.getHand()!=EquipmentSlot.HAND||!isWand(event.getItem()))return;Player player=event.getPlayer();SelectionType type=selectionTypes.getOrDefault(player.getUniqueId(),SelectionType.CUBOID);if(type==SelectionType.POLY&&player.isSneaking()&&event.getAction()==Action.LEFT_CLICK_AIR){event.setCancelled(true);if(authorized(player)&&requireBuildMode(player))clearPoly(player);return;}if(event.getClickedBlock()==null)return;event.setCancelled(true);if(!authorized(player)||!requireBuildMode(player))return;if(type==SelectionType.POLY){if(player.isSneaking()&&event.getAction()==Action.RIGHT_CLICK_BLOCK)removeNearestPolyPoint(player,event.getClickedBlock().getLocation());else if(player.isSneaking()&&event.getAction()==Action.LEFT_CLICK_BLOCK)clearPoly(player);else if(event.getAction()==Action.LEFT_CLICK_BLOCK||event.getAction()==Action.RIGHT_CLICK_BLOCK)addPolyPoint(player,event.getClickedBlock().getLocation());return;}if(event.getAction()==Action.LEFT_CLICK_BLOCK)setPosition(player,true,event.getClickedBlock().getLocation());else if(event.getAction()==Action.RIGHT_CLICK_BLOCK)setPosition(player,false,event.getClickedBlock().getLocation());}

    @EventHandler public void onQuit(PlayerQuitEvent event){UUID id=event.getPlayer().getUniqueId();Task task=active.remove(id);if(task!=null)task.cancelled=true;selections.remove(id);selectionTypes.remove(id);selectionVisualEnabled.remove(id);zoneVisuals.remove(id);clipboards.remove(id);histories.remove(id);}

    public boolean handle(CommandSender sender,String[]args,int offset){if(!(sender instanceof Player player)){sender.sendMessage(CC.color("&cOnly players can use admin world edit commands."));return true;}if(!authorized(player)){sender.sendMessage(CC.color("&cYou do not have permission to use this command."));return true;}if(args.length<=offset){usage(player);return true;}String command=args[offset].toLowerCase(Locale.ROOT);String[]values=Arrays.copyOfRange(args,offset+1,args.length);try{switch(command){
        case"wand"->giveWand(player);case"pos1"->setPosition(player,true,player.getLocation());case"pos2"->setPosition(player,false,player.getLocation());case"size","selinfo"->showSize(player);
        case"sel","selection"->{if(values.length==0)showSize(player);else setSelectionType(player,values[0]);}
        case"poly"->polyCommand(player,values);case"selpreview","selvisual","selectionvisual","wevisual"->previewCommand(player,values);
        case"count"->count(player,values);case"copy"->copy(player,false);case"cancel"->cancel(player);case"expand","contract","shift"->resize(player,command,values);
        case"undo"->{if(requireBuildMode(player))undo(player);}case"set","walls","replace","cut","clear","paste","sphere","hsphere","cyl","hcyl"->{if(requireBuildMode(player))edit(player,command,values);}default->usage(player);
    }}catch(IllegalArgumentException exception){player.sendMessage(CC.color("&cInvalid command arguments."));}catch(Exception exception){plugin.getLogger().warning("Built-in world edit command failed for "+player.getName()+": "+exception.getMessage());player.sendMessage(CC.color("&cWorldEdit task failed: &e"+safeReason(exception)));}return true;}

    private void edit(Player p,String command,String[]args){if(hasTask(p))return;switch(command){
        case"paste"->paste(p);case"sphere","hsphere"->sphere(p,args,command.equals("hsphere"));case"cyl","hcyl"->cylinder(p,args,command.equals("hcyl"));
        case"set"->{if(args.length<1){usage(p,"//set <block>");return;}Material to=parseBlock(p,args[0]);if(to!=null)selectionEdit(p,"set",args[0],to,null,false,false);}
        case"clear"->selectionEdit(p,"clear","air",Material.AIR,null,false,false);
        case"walls"->{if(args.length<1){usage(p,"//walls <block>");return;}Material to=parseBlock(p,args[0]);if(to!=null)selectionEdit(p,"walls",args[0],to,null,true,false);}
        case"replace"->{if(args.length<2){usage(p,"//replace <from> <to>");return;}Material from=parseBlock(p,args[0]),to=parseBlock(p,args[1]);if(from!=null&&to!=null)selectionEdit(p,"replace",args[0]+" -> "+args[1],to,from,false,false);}
        case"cut"->selectionEdit(p,"cut","air",Material.AIR,null,false,true);
    }}

    private void selectionEdit(Player p,String command,String display,Material target,Material replace,boolean walls,boolean capture){Selection s=requireSelection(p);if(s==null)return;List<Pos>positions=positions(s,walls);if(!checkLimit(p,positions.size()))return;Task task=Task.edit(p,command,positions,Bukkit.createBlockData(target),replace,capture?p.getLocation():null);task.finishMessage=switch(command){case"set"->"&aSet &e%changed% &ablocks to &e"+display+"&a.";case"walls"->"&aCreated walls using &e"+display+"&a.";case"replace"->"&aReplaced &e"+display+"&a.";case"clear"->"&aCleared &e%changed% &ablocks.";case"cut"->"&aCut &e%changed% &ablocks to clipboard.";default->"&aWorldEdit task complete: &e%changed% &ablocks changed.";};start(task);}

    private void copy(Player p,boolean cut){if(hasTask(p))return;Selection s=requireSelection(p);if(s==null)return;List<Pos>positions=positions(s);if(!checkLimit(p,positions.size()))return;Task task=Task.read(p,cut?"cut-copy":"copy",positions,ReadMode.COPY,null,p.getLocation());task.finishMessage="&aCopied &e%total% &ablocks to clipboard.";start(task);}
    private void count(Player p,String[]args){if(args.length<1){usage(p,"//count <block>");return;}if(hasTask(p))return;Material material=parseBlock(p,args[0]);Selection s=requireSelection(p);if(material==null||s==null)return;List<Pos>positions=positions(s);if(!checkLimit(p,positions.size()))return;Task task=Task.read(p,"count",positions,ReadMode.COUNT,material,null);task.finishMessage="&aFound &e%matched% &ablocks matching &e"+args[0]+"&a.";start(task);}

    private void paste(Player p){Clipboard clipboard=clipboards.get(p.getUniqueId());if(clipboard==null){p.sendMessage(CC.color("&cYour clipboard is empty."));return;}Location at=p.getLocation();List<Pos>positions=new ArrayList<>(clipboard.entries.size());List<BlockData>targets=new ArrayList<>(clipboard.entries.size());for(ClipEntry entry:clipboard.entries){positions.add(new Pos(p.getWorld().getUID(),at.getBlockX()+entry.dx,at.getBlockY()+entry.dy,at.getBlockZ()+entry.dz));targets.add(entry.data.clone());}if(!checkLimit(p,positions.size()))return;Task task=Task.paste(p,"paste",positions,targets);task.finishMessage="&aPasted clipboard.";start(task);}

    private void undo(Player p){if(hasTask(p))return;Deque<UndoSnapshot>history=histories.get(p.getUniqueId());if(history==null||history.isEmpty()){p.sendMessage(CC.color("&cYou do not have any world edit actions to undo."));return;}UndoSnapshot snapshot=history.removeLast();List<Pos>positions=new ArrayList<>(snapshot.blocks.size());List<BlockData>targets=new ArrayList<>(snapshot.blocks.size());for(SavedBlock block:snapshot.blocks){positions.add(block.pos);targets.add(block.data.clone());}Task task=Task.paste(p,"undo",positions,targets);task.recordUndo=false;task.finishMessage="&aUndid your last world edit action.";start(task);}

    private void sphere(Player p,String[]args,boolean hollow){if(args.length<2){usage(p,hollow?"//hsphere <block> <radius>":"//sphere <block> <radius>");return;}Material material=parseBlock(p,args[0]);int r=parseBounded(args[1],1,MAX_RADIUS);long estimate=(long)Math.ceil(4D/3D*Math.PI*r*r*r);if(material==null||!checkLimit(p,estimate))return;Location c=p.getLocation();List<Pos>positions=new ArrayList<>((int)Math.min(Integer.MAX_VALUE,estimate));double inner=(r-1)*(r-1),outer=r*r;for(int x=-r;x<=r;x++)for(int y=-r;y<=r;y++)for(int z=-r;z<=r;z++){double d=x*x+y*y+z*z;if(d>outer||(hollow&&d<inner))continue;positions.add(new Pos(p.getWorld().getUID(),c.getBlockX()+x,c.getBlockY()+y,c.getBlockZ()+z));}shapeTask(p,hollow?"hsphere":"sphere",args[0],material,positions);}
    private void cylinder(Player p,String[]args,boolean hollow){if(args.length<3){usage(p,hollow?"//hcyl <block> <radius> <height>":"//cyl <block> <radius> <height>");return;}Material material=parseBlock(p,args[0]);int r=parseBounded(args[1],1,MAX_RADIUS),height=parseBounded(args[2],1,MAX_HEIGHT);long estimate=(long)Math.ceil(Math.PI*r*r*height);if(material==null||!checkLimit(p,estimate))return;Location c=p.getLocation();List<Pos>positions=new ArrayList<>((int)Math.min(Integer.MAX_VALUE,estimate));double inner=(r-1)*(r-1),outer=r*r;for(int x=-r;x<=r;x++)for(int z=-r;z<=r;z++){double d=x*x+z*z;if(d>outer||(hollow&&d<inner))continue;for(int y=0;y<height;y++)positions.add(new Pos(p.getWorld().getUID(),c.getBlockX()+x,c.getBlockY()+y,c.getBlockZ()+z));}shapeTask(p,hollow?"hcyl":"cyl",args[0],material,positions);}
    private void shapeTask(Player p,String command,String display,Material material,List<Pos>positions){if(hasTask(p)||!checkLimit(p,positions.size()))return;Task task=Task.edit(p,command,positions,Bukkit.createBlockData(material),null,null);task.finishMessage="&aCreated &e"+command+" &ausing &e"+display+"&a. (&e%changed% &ablocks)";start(task);}

    private long ticks;
    private void tick(){if(++ticks%20L==0L)previewSelections();if(active.isEmpty())return;int budget=batchSize();for(Task task:new ArrayList<>(active.values())){if(task.cancelled){completeCancelled(task);continue;}try{int allowance=Math.max(1,budget/Math.max(1,active.size()));process(task,allowance);}catch(Exception exception){fail(task,safeReason(exception));}}}
    private void process(Task task,int allowance){Player player=Bukkit.getPlayer(task.owner);if(player==null){active.remove(task.owner);return;}int processed=0;while(processed++<allowance&&task.cursor<task.positions.size()){Pos pos=task.positions.get(task.cursor);World world=Bukkit.getWorld(pos.world);if(world==null){fail(task,"world is unavailable");return;}if(!world.isChunkLoaded(pos.x>>4,pos.z>>4)){fail(task,"an edited chunk is not loaded");return;}Block block=world.getBlockAt(pos.x,pos.y,pos.z);
        if(task.phase==Phase.VALIDATE){if(!canEdit(player,block)){fail(task,"this area is protected");return;}if(task.captureOrigin!=null)task.captured.add(new ClipEntry(pos.x-task.captureOrigin.getBlockX(),pos.y-task.captureOrigin.getBlockY(),pos.z-task.captureOrigin.getBlockZ(),block.getBlockData().clone()));task.cursor++;}
        else if(task.readMode==ReadMode.COPY){task.captured.add(new ClipEntry(pos.x-task.captureOrigin.getBlockX(),pos.y-task.captureOrigin.getBlockY(),pos.z-task.captureOrigin.getBlockZ(),block.getBlockData().clone()));task.cursor++;}
        else if(task.readMode==ReadMode.COUNT){if(block.getType()==task.match)task.matched++;task.cursor++;}
        else{BlockData target=task.targets==null?task.target:task.targets.get(task.cursor);if(task.match==null||block.getType()==task.match){if(!block.getBlockData().matches(target)){task.undo.add(new SavedBlock(pos,block.getBlockData().clone()));block.setBlockData(target.clone(),false);task.changed++;}}task.cursor++;}}
        if(task.cursor>=task.positions.size()){if(task.phase==Phase.VALIDATE){task.phase=Phase.APPLY;task.cursor=0;if(task.captureOrigin!=null){clipboards.put(task.owner,new Clipboard(List.copyOf(task.captured)));task.captured.clear();}}else complete(task);}else reportProgress(task,player);}

    private void start(Task task){Player p=Bukkit.getPlayer(task.owner);if(task.readMode==ReadMode.NONE&&containsProtectedEntity(task.positions)){if(p!=null)p.sendMessage(CC.color("&cThis area is protected. Enable &e/buildmode &cand make sure you have permission."));return;}active.put(task.owner,task);if(p!=null)p.sendMessage(CC.color("&aStarted WorldEdit task &e"+task.name+"&a with &e"+task.positions.size()+" &ablocks."));}
    private boolean containsProtectedEntity(List<Pos> positions){if(positions.isEmpty())return false;Pos first=positions.getFirst();World world=Bukkit.getWorld(first.world);if(world==null)return true;int minX=Integer.MAX_VALUE,minY=Integer.MAX_VALUE,minZ=Integer.MAX_VALUE,maxX=Integer.MIN_VALUE,maxY=Integer.MIN_VALUE,maxZ=Integer.MIN_VALUE;for(Pos pos:positions){if(!pos.world.equals(first.world))return true;minX=Math.min(minX,pos.x);minY=Math.min(minY,pos.y);minZ=Math.min(minZ,pos.z);maxX=Math.max(maxX,pos.x);maxY=Math.max(maxY,pos.y);maxZ=Math.max(maxZ,pos.z);}BoundingBox box=new BoundingBox(minX,minY,minZ,maxX+1D,maxY+1D,maxZ+1D);return world.getNearbyEntities(box,entity->entity.getPersistentDataContainer().has(furnitureKey)||entity.getPersistentDataContainer().has(npcKey)).size()>0;}
    private void complete(Task task){active.remove(task.owner);Player player=Bukkit.getPlayer(task.owner);if(task.readMode==ReadMode.COPY)clipboards.put(task.owner,new Clipboard(List.copyOf(task.captured)));if(task.recordUndo&&!task.undo.isEmpty()){Deque<UndoSnapshot>history=histories.computeIfAbsent(task.owner,k->new ArrayDeque<>());history.addLast(new UndoSnapshot(List.copyOf(task.undo)));while(history.size()>MAX_HISTORY)history.removeFirst();}if(player!=null){String message=task.finishMessage.replace("%changed%",String.valueOf(task.changed)).replace("%total%",String.valueOf(task.positions.size())).replace("%matched%",String.valueOf(task.matched));player.sendMessage(CC.color(message));log(player,task.name,task.positions.size());}}
    private void completeCancelled(Task task){active.remove(task.owner);if(task.recordUndo&&!task.undo.isEmpty()){histories.computeIfAbsent(task.owner,k->new ArrayDeque<>()).addLast(new UndoSnapshot(List.copyOf(task.undo)));}Player p=Bukkit.getPlayer(task.owner);if(p!=null)p.sendMessage(CC.color("&cCancelled your current world edit task."));}
    private void fail(Task task,String reason){active.remove(task.owner);if(task.recordUndo&&!task.undo.isEmpty())histories.computeIfAbsent(task.owner,k->new ArrayDeque<>()).addLast(new UndoSnapshot(List.copyOf(task.undo)));Player p=Bukkit.getPlayer(task.owner);if(p!=null)p.sendMessage(CC.color("&cWorldEdit task failed: &e"+reason));}
    private void reportProgress(Task task,Player player){long now=System.currentTimeMillis();if(now-task.lastReport<3000)return;task.lastReport=now;double percent=task.positions.isEmpty()?100D:task.cursor*100D/task.positions.size();player.sendMessage(CC.color("&aWorldEdit task &e"+task.name+"&a: &b"+String.format(Locale.US,"%.1f",percent)+"% &7("+task.cursor+"/"+task.positions.size()+")"));}

    private boolean canEdit(Player p,Block b){if(!spawn.isBuildMode(p))return false;if(spawn.isHub(b.getLocation())&&!spawn.canBuildInHub(p))return false;return zones.canPlace(p,b)&&zones.canBreak(p,b)&&guilds.canBuild(p,b.getLocation());}
    private int batchSize(){double tps=20D;try{Object value=Bukkit.class.getMethod("getTPS").invoke(null);if(value instanceof double[]values&&values.length>0)tps=values[0];}catch(Exception ignored){}if(tps<17D)return 250;if(tps<18.5D)return 750;return 2000;}
    private boolean hasTask(Player p){if(!active.containsKey(p.getUniqueId()))return false;p.sendMessage(CC.color("&cYou already have a world edit task running."));return true;}
    private void cancel(Player p){Task task=active.get(p.getUniqueId());if(task==null){p.sendMessage(CC.color("&cYou do not have a world edit task running."));return;}task.cancelled=true;}

    private Material parseBlock(Player p,String input){if(input==null||!input.matches("[a-zA-Z0-9_:]+")){p.sendMessage(CC.color("&cUnknown block: &e"+input));return null;}Material material=Material.matchMaterial(input,true);if(material==null||!material.isBlock()){p.sendMessage(CC.color("&cUnknown block: &e"+input));return null;}return material;}
    private int parseBounded(String value,int min,int max){int parsed=Integer.parseInt(value);if(parsed<min||parsed>max)throw new IllegalArgumentException();return parsed;}
    private boolean checkLimit(Player p,long blocks){if(blocks<=MAX_BLOCKS)return true;p.sendMessage(CC.color("&cSelection is too large: &e"+blocks+"&c/&e"+MAX_BLOCKS+"&c blocks."));return false;}
    private Selection requireSelection(Player p){Selection s=selections.get(p.getUniqueId());if(s==null||!s.complete()){p.sendMessage(CC.color(selectionTypes.getOrDefault(p.getUniqueId(),SelectionType.CUBOID)==SelectionType.POLY?"&cPoly selection needs at least 3 points.":"&cYour selection is incomplete. Set position 1 and position 2 first."));return null;}if(!s.world.equals(p.getWorld().getUID())){p.sendMessage(CC.color("&cYour selection is in another world. Clear it or return to that world."));return null;}return s;}
    private List<Pos> positions(Selection s){return positions(s,false);}
    private List<Pos> positions(Selection s,boolean walls){
        if(s.type==SelectionType.POLY&&walls)return polyWalls(s);
        // Refuse pathological bounding boxes before a malformed polygon can monopolize the server thread.
        if(s.boundingVolume()>MAX_BLOCKS*40L)return Collections.nCopies((int)MAX_BLOCKS+1,new Pos(s.world,s.minX,s.minY,s.minZ));
        List<Pos>result=new ArrayList<>((int)Math.min(MAX_BLOCKS+1,s.boundingVolume()));
        for(int x=s.minX;x<=s.maxX;x++)for(int y=s.minY;y<=s.maxY;y++)for(int z=s.minZ;z<=s.maxZ;z++){
            if(s.type==SelectionType.POLY&&!s.contains(x+0.5D,z+0.5D))continue;
            if(walls&&x>s.minX&&x<s.maxX&&z>s.minZ&&z<s.maxZ)continue;
            result.add(new Pos(s.world,x,y,z));
            if(result.size()>MAX_BLOCKS) return result;
        }
        return result;
    }
    private List<Pos> polyWalls(Selection s){Set<Long>columns=new LinkedHashSet<>();for(int i=0;i<s.points.size();i++){Point a=s.points.get(i),b=s.points.get((i+1)%s.points.size());int x=a.x,z=a.z,dx=Math.abs(b.x-a.x),dz=Math.abs(b.z-a.z),sx=a.x<b.x?1:-1,sz=a.z<b.z?1:-1,err=dx-dz;while(true){columns.add((((long)x)<<32)^(z&0xffffffffL));if(x==b.x&&z==b.z)break;int e=err*2;if(e>-dz){err-=dz;x+=sx;}if(e<dx){err+=dx;z+=sz;}}}List<Pos>result=new ArrayList<>();for(long key:columns){int x=(int)(key>>32),z=(int)key;for(int y=s.minY;y<=s.maxY;y++){result.add(new Pos(s.world,x,y,z));if(result.size()>MAX_BLOCKS)return result;}}return result;}

    private void setPosition(Player p,boolean first,Location l){if(selectionTypes.getOrDefault(p.getUniqueId(),SelectionType.CUBOID)==SelectionType.POLY){addPolyPoint(p,l);return;}Selection old=selections.get(p.getUniqueId());if(old!=null&&!old.world.equals(l.getWorld().getUID()))old=null;Point point=new Point(l.getBlockX(),l.getBlockY(),l.getBlockZ());Selection next=first?Selection.cuboid(l.getWorld().getUID(),point,old==null?null:old.pos2):Selection.cuboid(l.getWorld().getUID(),old==null?null:old.pos1,point);selections.put(p.getUniqueId(),next);p.sendMessage(CC.color("&aPosition "+(first?"1":"2")+" set to &e"+point.x+", "+point.y+", "+point.z+"&a."));}
    private void showSize(Player p){Selection s=requireSelection(p);if(s==null)return;long blocks=positions(s).size();World world=Bukkit.getWorld(s.world);p.sendMessage(CC.color("&7Type: &e"+(s.type==SelectionType.POLY?"Poly":"Cuboid")));p.sendMessage(CC.color("&7World: &e"+(world==null?"unknown":world.getName())));if(s.type==SelectionType.POLY){p.sendMessage(CC.color("&7Points: &e"+s.points.size()));p.sendMessage(CC.color("&7Height: &e"+s.minY+" &7to &e"+s.maxY));}else{p.sendMessage(CC.color("&7Pos1: &f"+s.pos1.x+", "+s.pos1.y+", "+s.pos1.z));p.sendMessage(CC.color("&7Pos2: &f"+s.pos2.x+", "+s.pos2.y+", "+s.pos2.z));}p.sendMessage(CC.color("&7Blocks: &e"+blocks));p.sendMessage(CC.color("&7Visual: "+(selectionVisualEnabled.getOrDefault(p.getUniqueId(),false)?"&aEnabled":"&cDisabled")));}
    private void resize(Player p,String command,String[]args){if(args.length<1){usage(p,"//"+command+" <amount> [direction]");return;}int amount=parseBounded(args[0],1,10000);Selection s=requireSelection(p);if(s==null)return;if(s.type==SelectionType.POLY){p.sendMessage(CC.color("&cExpand, contract and shift currently require a Cuboid selection."));return;}Point d=direction(p,args.length>1?args[1]:"me").multiply(amount);Point a=s.pos1,b=s.pos2;if(command.equals("shift")){a=a.add(d);b=b.add(d);}else{int sign=command.equals("expand")?1:-1;Point low=new Point(s.minX,s.minY,s.minZ),high=new Point(s.maxX,s.maxY,s.maxZ);if(d.x>0)high=high.add(new Point(amount*sign,0,0));if(d.x<0)low=low.add(new Point(-amount*sign,0,0));if(d.y>0)high=high.add(new Point(0,amount*sign,0));if(d.y<0)low=low.add(new Point(0,-amount*sign,0));if(d.z>0)high=high.add(new Point(0,0,amount*sign));if(d.z<0)low=low.add(new Point(0,0,-amount*sign));if(low.x>high.x||low.y>high.y||low.z>high.z){p.sendMessage(CC.color("&cThat contraction would invert the selection."));return;}a=low;b=high;}selections.put(p.getUniqueId(),Selection.cuboid(s.world,a,b));showSize(p);}
    private Point direction(Player p,String input){String key=input.toLowerCase(Locale.ROOT);if(key.equals("me")||key.equals("forward")){float yaw=(p.getLocation().getYaw()%360+360)%360;key=yaw>=45&&yaw<135?"west":yaw>=135&&yaw<225?"north":yaw>=225&&yaw<315?"east":"south";}return switch(key){case"north"->new Point(0,0,-1);case"south"->new Point(0,0,1);case"east"->new Point(1,0,0);case"west"->new Point(-1,0,0);case"up"->new Point(0,1,0);case"down"->new Point(0,-1,0);default->throw new IllegalArgumentException();};}

    private void setSelectionType(Player p,String value){SelectionType type;if(value.equalsIgnoreCase("cuboid"))type=SelectionType.CUBOID;else if(value.equalsIgnoreCase("poly"))type=SelectionType.POLY;else{p.sendMessage(CC.color("&cUnknown selection type. Use: &eCuboid&c, &ePoly&c."));return;}selectionTypes.put(p.getUniqueId(),type);selections.remove(p.getUniqueId());p.sendMessage(CC.color("&aSelection mode set to &e"+(type==SelectionType.POLY?"Poly":"Cuboid")+"&a."));}
    private void addPolyPoint(Player p,Location location){Selection old=selections.get(p.getUniqueId());if(old!=null&&(!old.world.equals(location.getWorld().getUID())||old.type!=SelectionType.POLY)){p.sendMessage(CC.color("&cAll poly points must be in the same world. Clear the selection first."));return;}List<Point>points=new ArrayList<>(old==null?List.of():old.points);if(points.size()>=MAX_POLY_POINTS){p.sendMessage(CC.color("&cYou cannot add more than &e128 &cpoly points."));return;}Point point=new Point(location.getBlockX(),location.getBlockY(),location.getBlockZ());points.add(point);selections.put(p.getUniqueId(),Selection.poly(location.getWorld().getUID(),points));p.sendMessage(CC.color("&aAdded poly point &e#"+points.size()+" &7("+point.x+", "+point.y+", "+point.z+")."));}
    private void clearPoly(Player p){selections.remove(p.getUniqueId());p.sendMessage(CC.color("&aCleared poly selection."));}
    private void removeNearestPolyPoint(Player p,Location location){Selection s=selections.get(p.getUniqueId());if(s==null||s.type!=SelectionType.POLY||s.points.isEmpty()){p.sendMessage(CC.color("&cPoly selection has no points."));return;}int nearest=0;double distance=Double.MAX_VALUE;for(int i=0;i<s.points.size();i++){Point point=s.points.get(i);double current=Math.pow(point.x-location.getBlockX(),2)+Math.pow(point.y-location.getBlockY(),2)+Math.pow(point.z-location.getBlockZ(),2);if(current<distance){distance=current;nearest=i;}}removePolyPoint(p,nearest+1);}
    private void removePolyPoint(Player p,int number){Selection s=selections.get(p.getUniqueId());if(s==null||s.type!=SelectionType.POLY||number<1||number>s.points.size()){p.sendMessage(CC.color("&cInvalid poly point number."));return;}List<Point>points=new ArrayList<>(s.points);points.remove(number-1);selections.put(p.getUniqueId(),Selection.poly(s.world,points));p.sendMessage(CC.color("&aRemoved poly point &e#"+number+"&a."));}
    private void polyCommand(Player p,String[]args){if(selectionTypes.getOrDefault(p.getUniqueId(),SelectionType.CUBOID)!=SelectionType.POLY){p.sendMessage(CC.color("&cSet selection mode to Poly first with &e//sel poly&c."));return;}if(args.length==0){usage(p,"//poly <add|remove|clear|list|close>");return;}switch(args[0].toLowerCase(Locale.ROOT)){case"add"->addPolyPoint(p,p.getLocation());case"clear"->clearPoly(p);case"remove"->{if(args.length<2)usage(p,"//poly remove <pointNumber>");else removePolyPoint(p,Integer.parseInt(args[1]));}case"list"->{Selection s=selections.get(p.getUniqueId());if(s==null||s.points.isEmpty()){p.sendMessage(CC.color("&cPoly selection has no points."));return;}for(int i=0;i<s.points.size();i++){Point point=s.points.get(i);p.sendMessage(CC.color("&e#"+(i+1)+" &7- &f"+point.x+", "+point.y+", "+point.z));}}case"close"->{Selection s=requireSelection(p);if(s!=null)p.sendMessage(CC.color("&aClosed poly selection with &e"+s.points.size()+" &apoints."));}default->usage(p,"//poly <add|remove|clear|list|close>");}}
    private void previewCommand(Player p,String[]args){boolean current=selectionVisualEnabled.getOrDefault(p.getUniqueId(),false);String mode=args.length==0?"toggle":args[0].toLowerCase(Locale.ROOT);if(!Set.of("on","off","toggle").contains(mode)){usage(p,"//selvisual [on|off|toggle]");return;}boolean enabled=mode.equals("toggle")?!current:mode.equals("on");if(enabled==current&&!mode.equals("toggle")){p.sendMessage(CC.color(enabled?"&eSelection particles are already enabled.":"&eSelection particles are already disabled."));return;}if(enabled)selectionVisualEnabled.put(p.getUniqueId(),true);else selectionVisualEnabled.remove(p.getUniqueId());p.sendMessage(CC.color(enabled?"&aSelection particles enabled.":"&cSelection particles disabled."));}
    private void previewSelections(){for(Player p:Bukkit.getOnlinePlayers()){if(!authorized(p))continue;int[]budget={MAX_PREVIEW_PARTICLES};if(selectionVisualEnabled.getOrDefault(p.getUniqueId(),false)){Selection s=selections.get(p.getUniqueId());if(s!=null&&s.complete()&&s.world.equals(p.getWorld().getUID()))drawSelection(p,s,Particle.END_ROD,budget);}ZoneVisual zone=zoneVisuals.get(p.getUniqueId());if(zone!=null&&zone.selection.world.equals(p.getWorld().getUID()))drawSelection(p,zone.selection,Particle.ELECTRIC_SPARK,budget);}}
    private void drawSelection(Player p,Selection s,Particle border,int[]budget){List<Line>lines=new ArrayList<>();List<Point>markers=new ArrayList<>();if(s.type==SelectionType.CUBOID){Point[]c={new Point(s.minX,s.minY,s.minZ),new Point(s.maxX,s.minY,s.minZ),new Point(s.maxX,s.minY,s.maxZ),new Point(s.minX,s.minY,s.maxZ),new Point(s.minX,s.maxY,s.minZ),new Point(s.maxX,s.maxY,s.minZ),new Point(s.maxX,s.maxY,s.maxZ),new Point(s.minX,s.maxY,s.maxZ)};for(int i=0;i<4;i++){lines.add(new Line(c[i],c[(i+1)%4]));lines.add(new Line(c[i+4],c[4+(i+1)%4]));lines.add(new Line(c[i],c[i+4]));}markers.add(s.pos1);markers.add(s.pos2);}else{markers.addAll(s.points);if(s.points.size()>=2){int edges=s.points.size()>=3?s.points.size():s.points.size()-1;for(int i=0;i<edges;i++){Point a=s.points.get(i),b=s.points.get((i+1)%s.points.size());lines.add(new Line(new Point(a.x,s.minY,a.z),new Point(b.x,s.minY,b.z)));lines.add(new Line(new Point(a.x,s.maxY,a.z),new Point(b.x,s.maxY,b.z)));}for(Point point:s.points)lines.add(new Line(new Point(point.x,s.minY,point.z),new Point(point.x,s.maxY,point.z)));}}double total=lines.stream().mapToDouble(Line::length).sum();double step=Math.max(1D,total/Math.max(1,budget[0]-markers.size()));for(Line line:lines)drawLine(p,line,border,step,budget);for(Point point:markers)spawnPreviewParticle(p,point.x+0.5D,point.y+0.5D,point.z+0.5D,Particle.HAPPY_VILLAGER,budget);}
    private void drawLine(Player p,Line line,Particle particle,double step,int[]budget){double length=line.length();int samples=Math.max(1,(int)Math.ceil(length/step));for(int i=0;i<=samples&&budget[0]>0;i++){double t=i/(double)samples;spawnPreviewParticle(p,line.a.x+0.5D+(line.b.x-line.a.x)*t,line.a.y+0.5D+(line.b.y-line.a.y)*t,line.a.z+0.5D+(line.b.z-line.a.z)*t,particle,budget);}}
    private void spawnPreviewParticle(Player p,double x,double y,double z,Particle particle,int[]budget){if(budget[0]<=0)return;Location at=new Location(p.getWorld(),x,y,z);if(at.distanceSquared(p.getLocation())>MAX_VISUAL_DISTANCE_SQUARED||!p.getWorld().isChunkLoaded(at.getBlockX()>>4,at.getBlockZ()>>4))return;p.spawnParticle(particle,x,y,z,1,0,0,0,0);budget[0]--;}

    public void showZoneVisual(Player player,String zoneId,SelectionSnapshot snapshot){Selection selection=fromSnapshot(snapshot);if(selection==null)return;zoneVisuals.put(player.getUniqueId(),new ZoneVisual(zoneId,selection));}
    public void clearZoneVisual(Player player){zoneVisuals.remove(player.getUniqueId());}
    private Selection fromSnapshot(SelectionSnapshot snapshot){if(snapshot==null||snapshot.world()==null)return null;World world=Bukkit.getWorld(snapshot.world());if(world==null)return null;if(snapshot.type()==SelectionType.CUBOID){if(snapshot.pos1()==null||snapshot.pos2()==null)return null;return Selection.cuboid(world.getUID(),point(snapshot.pos1()),point(snapshot.pos2()));}List<Point>points=new ArrayList<>();for(int i=0;i<snapshot.points().size();i++){SelectionPoint point=snapshot.points().get(i);points.add(new Point(point.x(),i==1?snapshot.maxY():snapshot.minY(),point.z()));}return Selection.poly(world.getUID(),points);}
    private Point point(SelectionPoint point){return new Point(point.x(),point.y(),point.z());}

    public SelectionSnapshot getSelection(Player player){Selection s=requireSelection(player);if(s==null)return null;World world=Bukkit.getWorld(s.world);return new SelectionSnapshot(s.type,world==null?null:world.getName(),s.minY,s.maxY,s.pos1==null?null:new SelectionPoint(s.pos1.x,s.pos1.y,s.pos1.z),s.pos2==null?null:new SelectionPoint(s.pos2.x,s.pos2.y,s.pos2.z),s.points.stream().map(point->new SelectionPoint(point.x,point.y,point.z)).toList());}
    public enum SelectionType{CUBOID,POLY}
    public record SelectionPoint(int x,int y,int z){}
    public record SelectionSnapshot(SelectionType type,String world,int minY,int maxY,SelectionPoint pos1,SelectionPoint pos2,List<SelectionPoint>points){}

    private void giveWand(Player p){ItemStack wand=new ItemStack(Material.WOODEN_AXE);ItemMeta meta=wand.getItemMeta();meta.setDisplayName(CC.color("&aAdmin WorldEdit Wand"));meta.setLore(List.of(CC.color("&7Cuboid: &eLeft/Right set corners"),CC.color("&7Poly: &eClick to add points"),CC.color("&7Sneak Right: &eRemove nearest point"),CC.color("&7Sneak Left: &eClear poly selection"),"",CC.color("&cRequires buildmode.")));meta.getPersistentDataContainer().set(wandKey,PersistentDataType.BYTE,(byte)1);wand.setItemMeta(meta);p.getInventory().addItem(wand);p.sendMessage(CC.color("&aWorldEdit wand added to your inventory."));}
    private boolean isWand(ItemStack item){return item!=null&&item.hasItemMeta()&&Byte.valueOf((byte)1).equals(item.getItemMeta().getPersistentDataContainer().get(wandKey,PersistentDataType.BYTE));}
    private boolean authorized(Player p){return p.hasPermission("fakevival.worldedit.admin");}
    private boolean requireBuildMode(Player p){if(spawn.isBuildMode(p))return true;p.sendMessage(CC.color("&cYou must enable &e/buildmode &cto use admin world edit commands."));return false;}
    private void log(Player p,String command,long blocks){Location l=p.getLocation();String line=p.getName()+" used //"+command+" in "+p.getWorld().getName()+" at "+l.getBlockX()+" "+l.getBlockY()+" "+l.getBlockZ()+" selection="+blocks;plugin.getLogger().info(line);if(webhook!=null)webhook.sendAdminCommandLog("Admin world edit used","**"+line+"**");}
    private String safeReason(Exception e){String message=e.getMessage();return message==null||message.isBlank()?e.getClass().getSimpleName():message.replace('\n',' ').replace('\r',' ');}
    private void usage(Player p,String value){p.sendMessage(CC.color("&cUsage: "+value));}
    private void usage(Player p){p.sendMessage(CC.color("&eWorld edit: &f//sel <cuboid|poly>, //poly, //selpreview, //wand, //pos1, //pos2, //set, //walls, //replace, //copy, //paste, //cut, //clear, //undo, //cancel, //sphere, //cyl, //count, //size"));}
    public void shutdown(){if(schedulerTask!=-1)Bukkit.getScheduler().cancelTask(schedulerTask);schedulerTask=-1;active.clear();histories.clear();clipboards.clear();selections.clear();selectionTypes.clear();selectionVisualEnabled.clear();zoneVisuals.clear();}

    private enum Phase{VALIDATE,APPLY} private enum ReadMode{NONE,COPY,COUNT}
    private static final class Task{final UUID owner;final String name;final List<Pos>positions;final BlockData target;final List<BlockData>targets;final Material match;final ReadMode readMode;final Location captureOrigin;final List<SavedBlock>undo=new ArrayList<>();final List<ClipEntry>captured=new ArrayList<>();Phase phase;int cursor,changed;long matched,lastReport;boolean recordUndo=true,cancelled;String finishMessage="&aWorldEdit task complete: &e%changed% &ablocks changed.";private Task(Player p,String name,List<Pos>positions,BlockData target,List<BlockData>targets,Material match,ReadMode readMode,Location origin,Phase phase){owner=p.getUniqueId();this.name=name;this.positions=positions;this.target=target;this.targets=targets;this.match=match;this.readMode=readMode;captureOrigin=origin==null?null:origin.clone();this.phase=phase;}static Task edit(Player p,String n,List<Pos>pos,BlockData target,Material match,Location origin){return new Task(p,n,pos,target,null,match,ReadMode.NONE,origin,Phase.VALIDATE);}static Task paste(Player p,String n,List<Pos>pos,List<BlockData>targets){return new Task(p,n,pos,null,targets,null,ReadMode.NONE,null,Phase.VALIDATE);}static Task read(Player p,String n,List<Pos>pos,ReadMode mode,Material match,Location origin){Task t=new Task(p,n,pos,null,null,match,mode,origin,Phase.APPLY);t.recordUndo=false;return t;}}
    private record Pos(UUID world,int x,int y,int z){} private record SavedBlock(Pos pos,BlockData data){} private record ClipEntry(int dx,int dy,int dz,BlockData data){} private record Clipboard(List<ClipEntry>entries){} private record UndoSnapshot(List<SavedBlock>blocks){}
    private record Point(int x,int y,int z){Point add(Point o){return new Point(x+o.x,y+o.y,z+o.z);}Point multiply(int n){return new Point(x*n,y*n,z*n);}}
    private record Line(Point a,Point b){double length(){return Math.sqrt(Math.pow(b.x-a.x,2)+Math.pow(b.y-a.y,2)+Math.pow(b.z-a.z,2));}}
    private record ZoneVisual(String zoneId,Selection selection){}
    private static final class Selection{final SelectionType type;final UUID world;final Point pos1,pos2;final List<Point>points;final int minX,minY,minZ,maxX,maxY,maxZ;private Selection(SelectionType type,UUID world,Point a,Point b,List<Point>points){this.type=type;this.world=world;pos1=a;pos2=b;this.points=List.copyOf(points);List<Point>bounds=type==SelectionType.POLY?points:(a==null||b==null?List.of():List.of(a,b));if(bounds.isEmpty()){minX=minY=minZ=maxX=maxY=maxZ=0;}else{minX=bounds.stream().mapToInt(Point::x).min().orElse(0);minY=bounds.stream().mapToInt(Point::y).min().orElse(0);minZ=bounds.stream().mapToInt(Point::z).min().orElse(0);maxX=bounds.stream().mapToInt(Point::x).max().orElse(0);maxY=bounds.stream().mapToInt(Point::y).max().orElse(0);maxZ=bounds.stream().mapToInt(Point::z).max().orElse(0);}}static Selection cuboid(UUID world,Point a,Point b){return new Selection(SelectionType.CUBOID,world,a,b,List.of());}static Selection poly(UUID world,List<Point>points){return new Selection(SelectionType.POLY,world,null,null,points);}boolean complete(){return type==SelectionType.POLY?points.size()>=3:pos1!=null&&pos2!=null;}long width(){return(long)maxX-minX+1;}long height(){return(long)maxY-minY+1;}long length(){return(long)maxZ-minZ+1;}long boundingVolume(){try{return Math.multiplyExact(Math.multiplyExact(width(),height()),length());}catch(ArithmeticException e){return Long.MAX_VALUE;}}long volume(){return boundingVolume();}boolean contains(double x,double z){boolean inside=false;for(int i=0,j=points.size()-1;i<points.size();j=i++){Point a=points.get(i),b=points.get(j);if(((a.z>z)!=(b.z>z))&&(x<(double)(b.x-a.x)*(z-a.z)/(double)(b.z-a.z)+a.x))inside=!inside;}return inside;}}
}
